//! Configuration.
//!
//! * [`SystemConfig`] — generated by NixOS into `/etc/resilience/system.toml`,
//!   read-only for users. Override the path with `RESILIENCE_SYSTEM_CONFIG`
//!   for development on a non-Resilience host.
//! * [`UserSettings`] — per-user preferences (theme) in
//!   `$XDG_CONFIG_HOME/resilience/settings.toml`. Preferences never grant
//!   capabilities; the security mode comes from [`crate::mode::detect`].

use std::fs;
use std::io::Write;
use std::net::SocketAddr;
use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};
use std::path::{Path, PathBuf};
use std::time::Duration;

use serde::{Deserialize, Serialize};
use thiserror::Error;

use crate::network::ProbeConfig;

pub const SYSTEM_CONFIG_PATH: &str = "/etc/resilience/system.toml";

#[derive(Debug, Error)]
pub enum ConfigError {
    #[error("cannot read {path}: {source}")]
    Io {
        path: PathBuf,
        source: std::io::Error,
    },
    #[error("invalid {path}: {source}")]
    Parse {
        path: PathBuf,
        source: toml::de::Error,
    },
    #[error("cannot save settings: {0}")]
    Save(String),
}

#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct SystemConfig {
    pub edition: String,
    pub version: String,
    pub catalog: PathBuf,
    pub handbook_dir: PathBuf,
    /// Editor argv used for notes; the file path is appended.
    pub editor: Vec<String>,
    /// Editor argv used for notes in Ultra-Stable mode.
    pub restricted_editor: Vec<String>,
    /// Interactive shell offered to Stable/Advanced accounts.
    pub shell: Vec<String>,
    pub probe: ProbeSettings,
    pub tools: ToolPaths,
}

/// Programs used for removable media and backups. Absolute store paths on
/// Resilience; bare names (looked up in `PATH`) on development hosts.
#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct ToolPaths {
    pub lsblk: String,
    pub udisksctl: String,
    pub tar: String,
    pub zstd: String,
    pub age: String,
    pub sha256sum: String,
    /// The unprivileged backup tool `resilience-backup`.
    pub backup: String,
    /// NetworkManager's command-line client (Wi-Fi, ADR 0010).
    pub nmcli: String,
}

impl Default for ToolPaths {
    fn default() -> Self {
        ToolPaths {
            lsblk: "lsblk".into(),
            udisksctl: "udisksctl".into(),
            tar: "tar".into(),
            zstd: "zstd".into(),
            age: "age".into(),
            sha256sum: "sha256sum".into(),
            backup: "resilience-backup".into(),
            nmcli: "nmcli".into(),
        }
    }
}

impl ToolPaths {
    pub fn backup_tools(&self) -> crate::backup::Tools {
        crate::backup::Tools {
            tar: self.tar.clone(),
            zstd: self.zstd.clone(),
            age: self.age.clone(),
            sha256sum: self.sha256sum.clone(),
        }
    }
}

impl Default for SystemConfig {
    fn default() -> Self {
        SystemConfig {
            edition: "development".into(),
            version: crate::VERSION.into(),
            catalog: "/etc/resilience/apps.toml".into(),
            handbook_dir: "/run/current-system/sw/share/resilience/handbook".into(),
            editor: vec!["nano".into()],
            restricted_editor: vec!["nano".into(), "--restricted".into()],
            shell: vec!["bash".into(), "-i".into()],
            probe: ProbeSettings::default(),
            tools: ToolPaths::default(),
        }
    }
}

#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct ProbeSettings {
    /// `ip:port` pairs contacted by the on-demand Internet probe.
    pub targets: Vec<String>,
    /// Hostname resolved by the on-demand DNS probe. Empty disables it.
    pub dns_name: String,
    pub timeout_ms: u64,
}

impl Default for ProbeSettings {
    fn default() -> Self {
        ProbeSettings {
            targets: vec!["9.9.9.9:443".into(), "1.1.1.1:443".into()],
            dns_name: "nixos.org".into(),
            timeout_ms: 2500,
        }
    }
}

impl ProbeSettings {
    /// Invalid targets are dropped (and reported), never fatal.
    pub fn to_probe_config(&self) -> (ProbeConfig, Vec<String>) {
        let mut invalid = Vec::new();
        let targets = self
            .targets
            .iter()
            .filter_map(|t| {
                t.parse::<SocketAddr>()
                    .map_err(|_| invalid.push(t.clone()))
                    .ok()
            })
            .collect();
        let timeout = Duration::from_millis(self.timeout_ms.clamp(100, 10_000));
        (
            ProbeConfig {
                targets,
                dns_name: self.dns_name.clone(),
                timeout,
            },
            invalid,
        )
    }
}

impl SystemConfig {
    pub fn parse(text: &str, path: &Path) -> Result<Self, ConfigError> {
        toml::from_str(text).map_err(|source| ConfigError::Parse {
            path: path.into(),
            source,
        })
    }

    /// Load the system configuration. A missing file yields defaults (for
    /// development hosts); a present but invalid file is an error.
    pub fn load() -> Result<(Self, PathBuf, bool), ConfigError> {
        let path: PathBuf = std::env::var_os("RESILIENCE_SYSTEM_CONFIG")
            .map(PathBuf::from)
            .unwrap_or_else(|| SYSTEM_CONFIG_PATH.into());
        match fs::read_to_string(&path) {
            Ok(text) => Ok((Self::parse(&text, &path)?, path, true)),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
                Ok((Self::default(), path, false))
            }
            Err(source) => Err(ConfigError::Io { path, source }),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "kebab-case")]
pub enum ThemeName {
    #[default]
    Green,
    Amber,
    Cyan,
    Mono,
}

impl ThemeName {
    pub const ALL: [ThemeName; 4] = [
        ThemeName::Green,
        ThemeName::Amber,
        ThemeName::Cyan,
        ThemeName::Mono,
    ];

    pub fn label(self) -> &'static str {
        match self {
            ThemeName::Green => "Classic Green CRT",
            ThemeName::Amber => "Amber Terminal",
            ThemeName::Cyan => "Cyan Industrial",
            ThemeName::Mono => "Monochrome (no colour)",
        }
    }
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(default)]
pub struct UserSettings {
    pub theme: ThemeName,
}

impl UserSettings {
    pub fn path(config_home: &Path) -> PathBuf {
        config_home.join("resilience").join("settings.toml")
    }

    /// Load settings; unreadable or invalid files fall back to defaults so a
    /// broken preference file can never lock a user out of the interface.
    pub fn load(path: &Path) -> (Self, Option<String>) {
        match fs::read_to_string(path) {
            Ok(t) => match toml::from_str(&t) {
                Ok(s) => (s, None),
                Err(e) => (
                    Self::default(),
                    Some(format!("settings ignored ({}): {e}", path.display())),
                ),
            },
            Err(_) => (Self::default(), None),
        }
    }

    /// Save atomically (write temp file with mode 0600, fsync, rename).
    pub fn save(&self, path: &Path) -> Result<(), ConfigError> {
        let err = |e: std::io::Error| ConfigError::Save(format!("{}: {e}", path.display()));
        let dir = path
            .parent()
            .ok_or_else(|| ConfigError::Save("no parent directory".into()))?;
        fs::create_dir_all(dir).map_err(err)?;
        let _ = fs::set_permissions(dir, fs::Permissions::from_mode(0o700));
        let text = toml::to_string(self).map_err(|e| ConfigError::Save(e.to_string()))?;
        let tmp = dir.join(".settings.toml.tmp");
        {
            let mut f = fs::OpenOptions::new()
                .write(true)
                .create(true)
                .truncate(true)
                .mode(0o600)
                .open(&tmp)
                .map_err(err)?;
            f.write_all(text.as_bytes()).map_err(err)?;
            f.sync_all().map_err(err)?;
        }
        fs::rename(&tmp, path).map_err(err)
    }
}

/// `$XDG_CONFIG_HOME` or `~/.config`.
pub fn config_home(home: &Path) -> PathBuf {
    xdg_dir("XDG_CONFIG_HOME").unwrap_or_else(|| home.join(".config"))
}

/// `$XDG_STATE_HOME` or `~/.local/state`.
pub fn state_home(home: &Path) -> PathBuf {
    xdg_dir("XDG_STATE_HOME").unwrap_or_else(|| home.join(".local/state"))
}

fn xdg_dir(var: &str) -> Option<PathBuf> {
    // The XDG spec requires absolute paths; relative values are ignored.
    std::env::var_os(var)
        .map(PathBuf::from)
        .filter(|p| p.is_absolute())
}

pub fn home_dir() -> PathBuf {
    std::env::var_os("HOME")
        .map(PathBuf::from)
        .filter(|p| p.is_absolute())
        .unwrap_or_else(|| "/".into())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn system_config_defaults_and_overrides() {
        let c = SystemConfig::parse(
            "edition = \"standard\"\n[probe]\ntimeout_ms = 50\n",
            Path::new("t"),
        )
        .expect("ok");
        assert_eq!(c.edition, "standard");
        assert_eq!(c.catalog, PathBuf::from("/etc/resilience/apps.toml"));
        let (p, invalid) = c.probe.to_probe_config();
        assert_eq!(p.timeout, Duration::from_millis(100), "timeout is clamped");
        assert_eq!(p.targets.len(), 2);
        assert!(invalid.is_empty());
        assert!(SystemConfig::parse("unknown_key = 1", Path::new("t")).is_err());
    }

    #[test]
    fn invalid_probe_targets_are_reported() {
        let s = ProbeSettings {
            targets: vec!["1.2.3.4:80".into(), "not an addr".into()],
            ..Default::default()
        };
        let (p, invalid) = s.to_probe_config();
        assert_eq!(p.targets.len(), 1);
        assert_eq!(invalid, vec!["not an addr"]);
    }

    #[test]
    fn settings_roundtrip_and_permissions() {
        let dir = std::env::temp_dir().join(format!("resilience-cfg-{}", std::process::id()));
        let path = UserSettings::path(&dir);
        let s = UserSettings {
            theme: ThemeName::Amber,
        };
        s.save(&path).expect("save");
        assert_eq!(UserSettings::load(&path), (s, None));
        let mode = fs::metadata(&path).expect("meta").permissions().mode() & 0o777;
        assert_eq!(mode, 0o600);
        fs::write(&path, "theme = \"neon\"").expect("w");
        let (loaded, warn) = UserSettings::load(&path);
        assert_eq!(loaded, UserSettings::default());
        assert!(warn.is_some());
        fs::remove_dir_all(&dir).expect("cleanup");
    }
}
